/// The gallery's example of `Barcode`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_alt = args.text("alt");
        let arg_hide_text = args.bool("hide_text");

        HStack::new((
            {
                let mut it = Barcode::qr("https://ravenrs.dev");
                it = it.alt(arg_alt.clone());
                if arg_hide_text {
                    it = it.hide_text();
                }
                it
            },
            Barcode::new(Symbology::Ean13, "789123456789"),
        ))
        .spacing(24.0)
    })
}

impl ComponentBook for Barcode {
    fn book() -> Meta {
        Meta::new("Data/Barcode", render)
            .summary("QR Code and linear barcodes that scanners can read.")
            .arg(ArgType::text("alt", "Link to the RavenRS site"))
            .arg(ArgType::bool("hide_text", false))
            .story("Example", Args::new())
    }
}
